     1→use std::ops::{Deref, DerefMut};
     2→
     3→use bls12_381::{traits::*, Scalar};
     4→
     5→/// A polynomial in monomial form over the field `Scalar`.
     6→///
     7→/// Internally stores coefficients in ascending order of degree:
     8→///
     9→/// ```text
    10→/// Layout: x^0 * a_0 + x^1 * a_1 + ... + x^(n-1) * a_(n-1)
    11→/// ```
    12→#[derive(Clone, Debug, Eq, PartialEq, Default)]
    13→pub struct PolyCoeff(pub Vec<Scalar>);
    14→
    15→impl PolyCoeff {
    16→    /// Adds two polynomials `self + other` and returns the result.
    17→    ///
    18→    /// Polynomials may have different lengths; the shorter one is padded with zeros.
    19→    ///
    20→    /// WARNINGS:
    21→    /// - For `a + b - b` to be equal to `a`, the number of coefficients must be the same,
    22→    ///   otherwise we have an additional `Scalar::ZERO` in the result, but this is not a use
    23→    ///   case we should encounter in this crate.
    24→    #[must_use]
    25→    pub fn add(&self, other: &Self) -> Self {
    26→        let mut result = self.clone();
    27→        if other.len() > result.len() {
    28→            result.resize(other.len(), Scalar::ZERO);
    29→        }
    30→        for (i, &b) in other.iter().enumerate() {
    31→            result[i] += b;
    32→        }
    33→        result
    34→    }
    35→
    36→    /// Computes the additive inverse `-self` and returns the result.
    37→    #[must_use]
    38→    pub fn neg(&self) -> Self {
    39→        Self(self.iter().map(|c| -*c).collect())
    40→    }
    41→
    42→    /// Subtracts `other` from `self`, returning `self - other`.
    43→    ///
    44→    /// Internally implemented as `self + (-other)`.
    45→    ///
    46→    /// WARNINGS:
    47→    /// - For `a + b - b` to be equal to `a`, the number of coefficients must be the same,
    48→    ///   otherwise we have an additional `Scalar::ZERO` in the result, but this is not a use
    49→    ///   case we should encounter in this crate.
    50→    #[must_use]
    51→    pub fn sub(&self, other: &Self) -> Self {
    52→        self.add(&other.neg())
    53→    }
    54→
    55→    /// Evaluates the polynomial at the given scalar point `x`.
    56→    ///
    57→    /// Uses Horner’s method for efficient evaluation.
    58→    #[must_use]
    59→    pub fn eval(&self, x: &Scalar) -> Scalar {
    60→        let mut result = Scalar::ZERO;
    61→        for coeff in self.iter().rev() {
    62→            result = result * x + coeff;
    63→        }
    64→        result
    65→    }
    66→
    67→    /// Multiplies two polynomials `self * other` and returns the result.
    68→    ///
    69→    /// The result has degree `self.degree() + other.degree()`.
    70→    #[must_use]
    71→    pub fn mul(&self, other: &Self) -> Self {
    72→        let mut result = Self(vec![
    73→            Scalar::ZERO;
    74→            (self.len() + other.len()).saturating_sub(1)
    75→        ]);
    76→        for (i, a) in self.iter().enumerate() {
    77→            for (j, b) in other.iter().enumerate() {
    78→                result[i + j] += a * b;
    79→            }
    80→        }
    81→        result
    82→    }
    83→}
    84→
    85→impl Deref for PolyCoeff {
    86→    type Target = Vec<Scalar>;
    87→
    88→    fn deref(&self) -> &Self::Target {
    89→        &self.0
    90→    }
    91→}
    92→
    93→impl DerefMut for PolyCoeff {
    94→    fn deref_mut(&mut self) -> &mut Self::Target {
    95→        &mut self.0
    96→    }
    97→}
    98→
    99→impl From<Vec<Scalar>> for PolyCoeff {
   100→    fn from(value: Vec<Scalar>) -> Self {
   101→        Self(value)
   102→    }
   103→}
   104→
   105→/// Given a list of points, this method will compute the polynomial
   106→/// Z(x) which is equal to zero when evaluated at each point.
   107→///
   108→/// Example: vanishing_poly([1, 2, 3]) = (x - 1)(x - 2)(x - 3)
   109→pub fn vanishing_poly(roots: &[Scalar]) -> PolyCoeff {
   110→    let mut poly = PolyCoeff(vec![Scalar::ONE]);
   111→    for root in roots {
   112→        poly = poly.mul(&PolyCoeff(vec![-root, Scalar::ONE]));
   113→    }
   114→    poly
   115→}
   116→
   117→/// Interpolates a polynomial in monomial form from a list of points (x_i, y_i).
   118→///
   119→/// Uses the classic Lagrange interpolation formula. The result is the unique
   120→/// polynomial of degree < n that passes through all points.
   121→///
   122→/// Time complexity is O(n^2). Intended for small inputs and testing only.
   123→pub fn lagrange_interpolate(points: &[(Scalar, Scalar)]) -> Option<PolyCoeff> {
   124→    // Number of interpolation points. The resulting polynomial has degree < n.
   125→    let n = points.len();
   126→
   127→    // Ensure there are at least two points to interpolate
   128→    assert!(n >= 2, "interpolation requires at least 2 points");
   129→
   130→    // Initialize the result polynomial to zero: result(x) = 0
   131→    let mut result = vec![Scalar::ZERO; n];
   132→
   133→    // Loop over each interpolation point (x_i, y_i)
   134→    for (i, &(x_i, y_i)) in points.iter().enumerate() {
   135→        // Start with the constant polynomial 1 for the Lagrange basis polynomial L_i(x)
   136→        let mut basis = vec![Scalar::ONE];
   137→
   138→        // This will accumulate the denominator: product of (x_i - x_j) for j ≠ i
   139→        let mut denom = Scalar::ONE;
   140→
   141→        // Construct L_i(x) = product over j ≠ i of (x - x_j)
   142→        for (j, &(x_j, _)) in points.iter().enumerate() {
   143→            if i == j {
   144→                continue;
   145→            }
   146→
   147→            // Multiply the denominator by (x_i - x_j)
   148→            denom *= x_i - x_j;
   149→
   150→            // Multiply the current basis polynomial by (x - x_j)
   151→            // If basis(x) = a_0 + a_1 * x + ... + a_d * x^d,
   152→            // then basis(x) * (x - x_j) becomes a polynomial of degree d+1:
   153→            //     new_coeff[k] = -x_j * a_k     for x^k
   154→            //     new_coeff[k+1] = a_k          for x^{k+1}
   155→            let mut next = vec![Scalar::ZERO; basis.len() + 1];
   156→            for (k, &coeff_k) in basis.iter().enumerate() {
   157→                next[k] -= coeff_k * x_j;
   158→                next[k + 1] += coeff_k;
   159→            }
   160→
   161→            // Replace the basis with the updated polynomial
   162→            basis = next;
   163→        }
   164→
   165→        // Compute the scaling factor = y_i / denom
   166→        let scale = y_i * denom.invert().expect("denominator must be non-zero");
   167→
   168→        // Add scale * basis(x) to the result polynomial
   169→        for (res_k, basis_k) in result.iter_mut().zip(basis) {
   170→            *res_k += scale * basis_k;
   171→        }
   172→    }
   173→
   174→    // Wrap the result in PolyCoeff and return
   175→    Some(PolyCoeff(result))
   176→}
   177→
   178→#[cfg(test)]
   179→mod tests {
   180→    use proptest::prelude::*;
   181→
   182→    use super::*;
   183→
   184→    /// Small helper function to generate a vector of `Scalar`s
   185→    fn arb_scalar_vec(max_len: usize) -> impl Strategy<Value = Vec<Scalar>> {
   186→        prop::collection::vec(any::<u64>().prop_map(Scalar::from), 0..=max_len)
   187→    }
   188→
   189→    fn naive_poly_eval(poly: &PolyCoeff, value: &Scalar) -> Scalar {
   190→        let mut result = Scalar::ZERO;
   191→        for (i, coeff) in poly.iter().enumerate() {
   192→            result += coeff * value.pow_vartime([i as u64]);
   193→        }
   194→        result
   195→    }
   196→
   197→    #[test]
   198→    fn basic_polynomial_add() {
   199→        let a = PolyCoeff(vec![Scalar::from(1), Scalar::from(2), Scalar::from(3)]);
   200→        let b = PolyCoeff(vec![Scalar::from(4), Scalar::from(5), Scalar::from(6)]);
   201→        let c = PolyCoeff(vec![Scalar::from(5), Scalar::from(7), Scalar::from(9)]);
   202→        assert_eq!(a.add(&b), c);
   203→
   204→        let a = PolyCoeff(vec![Scalar::from(2), Scalar::from(3)]);
   205→        let b = PolyCoeff(vec![Scalar::from(4), Scalar::from(5), Scalar::from(6)]);
   206→        let c = PolyCoeff(vec![Scalar::from(6), Scalar::from(8), Scalar::from(6)]);
   207→        assert_eq!(a.add(&b), c);
   208→    }
   209→
   210→    #[test]
